def predict(inp, size, truncate=None):
    N=size
    blocks=[]
    for r in range(N-1):
        for c in range(N-1):
            if inp[r][c]==2 and inp[r+1][c]==2 and inp[r][c+1]==2 and inp[r+1][c+1]==2:
                blocks.append((r,c))
    out=[row[:] for row in inp]
    for (r,c) in blocks:
        TL=inp[r-1][c-1] if r>0 and c>0 else None
        TR=inp[r-1][c+2] if r>0 and c+2<N else None
        BL=inp[r+2][c-1] if r+2<N and c>0 else None
        BR=inp[r+2][c+2] if r+2<N and c+2<N else None
        def draw(col, rr, cc, dr, dcc):
            while 0<=rr<N and 0<=cc<N:
                if truncate and (rr,cc) in truncate.get((r,c,col),set()):
                    break
                out[rr][cc]=col; rr+=dr; cc+=dcc
        if TL is not None: draw(TL, r-1, c+2, -1, 1)   # TL->TR up-right
        if TR is not None: draw(TR, r+2, c+2, 1, 1)    # TR->BR down-right
        if BR is not None: draw(BR, r+2, c-1, 1, -1)   # BR->BL down-left
        if BL is not None: draw(BL, r-1, c-1, -1, -1)  # BL->TL up-left
    return out

def check(inp, exp, size, truncate=None):
    p=predict(inp,size,truncate)
    mm=[(r,c,exp[r][c],p[r][c]) for r in range(size) for c in range(size) if exp[r][c]!=p[r][c]]
    return mm

